from math import log, isclose, floor, ceil

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if x <= 0 or n <= 0:
        return False
    exp = log(x, n)
    return isclose(exp, round(exp)) or isclose(n ** floor(exp), x) or isclose(n ** ceil(exp), x)
```

